def verified_sources():
    try:
        packed = base64.b85decode("".join(PAYLOAD.split()))
    except (ValueError, UnicodeError) as error:
        raise ValueError("构建文件内容不完整，请重新下载并上传 dedede-macos.py。") from error
    if hashlib.sha256(packed).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("构建文件完整性校验失败，请重新下载并上传 dedede-macos.py。")
    raw = zlib.decompress(packed)
    if len(raw) != PAYLOAD_RAW_BYTES or len(raw) > 200_000_000:
        raise ValueError("源码长度校验失败。")
    document = json.loads(raw)
    if document.get("format") != 1 or document.get("version") != VERSION:
        raise ValueError("源码版本不匹配。")
    sources = []
    names = set()
    for entry in document["files"]:
        name = entry["path"]
        relative = PurePosixPath(name)
        if (not relative.parts or relative.is_absolute() or ".." in relative.parts
                or "\\" in name or ":" in name or relative.parts[0] != PLATFORM
                or str(relative) != name or name.casefold() in names):
            raise ValueError("源码路径无效：" + name)
        names.add(name.casefold())
        data = base64.b64decode(entry["data"], validate=True)
        if len(data) != entry["bytes"] or hashlib.sha256(data).hexdigest() != entry["sha256"]:
            raise ValueError("源码校验失败：" + name)
        sources.append((relative, data, entry["sha256"]))
    if not sources:
        raise ValueError("源码为空。")
    return sources


def restore(directory: Path, sources):
    directory = directory.resolve()
    directory.mkdir(parents=True, exist_ok=True)
    targets = []
    # Check all target paths before changing any source file.
    for relative, data, digest in sources:
        target = directory.joinpath(*relative.parts)
        if target.is_symlink() or not target.resolve().is_relative_to(directory):
            raise ValueError("源码目标路径无效：" + str(relative))
        targets.append((target, data, digest))
    for target, data, _ in targets:
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(dir=target.parent, prefix=".dedede-", delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(data)
            os.replace(temporary, target)
        finally:
            if temporary is not None:
                temporary.unlink(missing_ok=True)
    # Detect truncated writes before platform builds begin.
    for target, _, digest in targets:
        with target.open("rb") as stream:
            if hashlib.file_digest(stream, "sha256").hexdigest() != digest:
                raise ValueError("源码写入校验失败：" + str(target))
    receipt = {"platform": PLATFORM, "version": VERSION, "passed": True, "files": len(sources), "payloadSha256": PAYLOAD_SHA256}
    (directory / "source-verification.json").write_text(json.dumps(receipt, indent=2) + "\n", encoding="utf-8")
    return receipt


def main():
    parser = argparse.ArgumentParser(description="Restore verified Dedede desktop sources.")
    parser.add_argument("--output-dir", type=Path, default=Path.cwd())
    parser.add_argument("--verify-only", action="store_true")
    arguments = parser.parse_args()
    sources = verified_sources()
    receipt = ({"platform": PLATFORM, "version": VERSION, "passed": True, "files": len(sources), "payloadSha256": PAYLOAD_SHA256}
               if arguments.verify_only else restore(arguments.output_dir, sources))
    print(json.dumps(receipt))


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print("桌面源码准备失败：" + str(error), file=sys.stderr)
        raise SystemExit(1)
